using var adapter = new LabScriptedAdapter();
using var c = new LabController(adapter);
string id = c.Submit("SetLevel", 50);
c.Timeout(id);
Console.WriteLine(c.Results[id]); // Unknown
Console.WriteLine(adapter.Sent.Count); // 1
adapter.Emit(new LabCompletion(id, c.Session, "Completed"));
Console.WriteLine(c.Results[id]); // Completed
adapter.Emit(new LabCompletion(id, c.Session, "Completed"));
Console.WriteLine(c.Applied); // 1

using var adapter = new LabScriptedAdapter { ThrowOnSend=true };
using var c = new LabController(adapter);
try { c.Submit("QueryState", 0); }
catch (IOException ex) { Console.WriteLine(ex.GetType().Name); }
Console.WriteLine(adapter.Sent.Count); // 0
Console.WriteLine(c.Results.Values.Contains("LocalException")); // True
adapter.ThrowOnSend=false;
string id=c.Submit("QueryState",0);
adapter.Emit(new LabCompletion(id,c.Session,"Completed"));
Console.WriteLine(c.Results[id]); // Completed
